inst✝ : NeZero N
c : M7.Action.Recipe N
⊢ (have F := Solver.originalF c;
        have initial := [setupWork N, originalWork c];
        if F = 1 then
          { outcome := Solver.Outcome.noLogical F, charges := initial, discoveryCalls := 0, optimizerCalls := 0 }
        else
          have search := DiscoveryResources.run c;
          have stageCharges := initial ++ [DiscoveryResources.charged N search];
          match Option.map Prod.snd search.selected with
          | none =>
            { outcome := Solver.Outcome.unrecognized F, charges := stageCharges, discoveryCalls := 1,
              optimizerCalls := 0 }
          | some choice =>
            have transformed := Discovery.transformed c choice;
            have a := M7.Supports.polynomial transformed.1;
            have b := M7.Supports.polynomial transformed.2;
            match PhysicalBridge.solve transformed with
            | none =>
              { outcome := Solver.Outcome.unrecognized F,
                charges := stageCharges ++ [transformWork N, M6.ActualTransfer.actualDistanceWork N a b],
                discoveryCalls := 1, optimizerCalls := 1 }
            | some (d, v, k) =>
              { outcome := Solver.Outcome.recognized F d (PhysicalBridge.undo (Discovery.action choice) v) choice k,
                charges := stageCharges ++ [transformWork N, M6.ActualTransfer.actualWitnessWork N a b k, undoWork N],
                discoveryCalls := 1, optimizerCalls := 1 }).charges.length ≤
    6

